-- Approved wing sword geometry and palette shared by hand and showroom.
local Catalog=require('combat.WeaponCatalog')
local M={}
local expanded -- read-only cache of the generated whole-weapon models
---@param model table generated by tools/weapon_gen/*.py
---@return table
local function ExpandModel(model)
    local scale=model.scale
    local data={route='W',vertices={},boxes={},displayHeight=model.height,
        bounds={min={table.unpack(model.bounds.min)},max={table.unpack(model.bounds.max)}},
        sockets=model.sockets,uvBase=model.bounds.min[2],uvHeight=model.height}
    local pos,col=model.pos,model.col
    for t=0,model.triangles-1 do
        local pb,cb=t*9,t*5
        local p={}
        for v=0,2 do p[v+1]={pos[pb+v*3+1]/scale,pos[pb+v*3+2]/scale,pos[pb+v*3+3]/scale} end
        local a,b,c=p[1],p[2],p[3]
        local ux,uy,uz=b[1]-a[1],b[2]-a[2],b[3]-a[3]
        local vx,vy,vz=c[1]-a[1],c[2]-a[2],c[3]-a[3]
        local nx,ny,nz=uy*vz-uz*vy,uz*vx-ux*vz,ux*vy-uy*vx
        local len=math.sqrt(nx*nx+ny*ny+nz*nz)
        if len>1e-12 then
            local n={nx/len,ny/len,nz/len}
            local w={col[cb+1]/100,col[cb+2]/100,col[cb+3]/100}
            for v=1,3 do
                data.vertices[#data.vertices+1]={p=p[v],n=n,c=w,shade=col[cb+4]/100,glow=col[cb+5]/100}
            end
        end
    end
    data.triangles=#data.vertices/3
    return data
end
function M.Data()
    expanded=expanded or ExpandModel(require('combat.models.WingSword'))
    return expanded
end
---@param colors table?
---@return table
function M.Palette(colors)
    local result={}
    for i,key in ipairs({'primary','secondary','accent'}) do
        local index=colors and colors[key] or ({3,1,2})[i]
        local preset=Catalog.ColorPresets[index] or Catalog.ColorPresets[({3,1,2})[i]]
        local c={}
        for n=1,3 do
            local value=preset.rgb[n]/255
            -- Ivory stone keeps its light mass; sapphire is a saturated inset.
            c[n]=i==1 and (.70+.30*value) or (i==3 and value*({.42,.66,.94})[n] or value)
        end
        result[key]=c
    end
    local grip=colors and Catalog.ColorPresets[colors.grip]
    if grip then
        result.grip={grip.rgb[1]/255*.45,grip.rgb[2]/255*.45,grip.rgb[3]/255*.55}
    else result.grip={.08,.15,.36} end -- default: deep navy
    return result
end
---@param job table
function M.Dispose(job)
    if job.disposed then return end
    job.disposed=true
    if job.material then job.material:Dispose();job.material=nil end
    job.data=nil
end
---@param parent Node
---@param colors table
---@param mask integer
---@param low boolean
---@param strength number
---@return table?
---@return string?
function M.Begin(parent,colors,mask,low,strength)
    local job={wingSword=true,index=1}
    local ok,err=pcall(function()
        job.data=M.Data();job.blueprint=job.data
        local path='model/forge-blades/WingSword.xml'
        local source=assert(cache:GetResource('Material',path),'blade material unavailable')
        job.material=assert(source:Clone('ForgeWingSword'),'blade material clone failed')
        for key,c in pairs(M.Palette(colors)) do
            job.material:SetShaderParameter(key..'_color',Variant(Color(c[1],c[2],c[3],1)))
        end
        job.material:SetShaderParameter('flow_strength',Variant(strength))
        job.node=parent:CreateChild('WingSword')
        job.geometry=assert(job.node:CreateComponent('CustomGeometry'),'CustomGeometry unavailable')
        local g=job.geometry
        g.viewMask=mask;g.lightMask=mask;g.zoneMask=mask;g.castShadows=not low
        g:BeginGeometry(0,TRIANGLE_LIST)
    end)
    if not ok then
        M.Dispose(job)
        if job.node then job.node:Remove() end
        return nil,tostring(err)
    end
    return job
end
---@param job table
---@return boolean
function M.Step(job)
    if job.complete then return true end
    assert(not job.disposed,'disposed blade job')
    local vertices=job.data.vertices
    -- At most 96 vertices/frame; Commit is indivisible on the native side.
    local last=math.min(#vertices,job.index+95)
    local g=job.geometry
    for i=job.index,last do
        local v=vertices[i]
        g:DefineVertex(Vector3(v.p[1],v.p[2],v.p[3]))
        g:DefineNormal(Vector3(v.n[1],v.n[2],v.n[3]))
        g:DefineColor(Color(v.c[1],v.c[2],v.c[3],v.shade))
        g:DefineTexCoord(Vector2(v.glow,(v.p[2]-job.data.uvBase)/job.data.uvHeight))
    end
    job.index=last+1
    if last<#vertices then return false end
    g:Commit();assert(g:SetMaterial(0,job.material)~=false,'blade material binding failed')
    job.complete=true
    return true
end
---@param mesh table
---@param strength number
function M.SetFlowStrength(mesh,strength)
    if not mesh.disposed then
        mesh.material:SetShaderParameter('flow_strength',Variant(strength))
    end
end
return M
